/* eslint-disable prettier/prettier */
// src/components/EmptyCoursesIOS.tsx
//
// iOS-only "My Courses" empty state, per Figma frame
// "Courses - My Courses - Empty Version": no course recommendations and no
// top tabs (CoursesScreen hides them on iOS while this is showing) — just a
// short message and four "Get started on IPM Hub" shortcuts.
//
// Android keeps using EmptyCoursesRecommendation.
//
// Spec source: Figma CSS from Marium (screen frame 390 wide, padding
// 16/16/0/16, gap 24; sections frame padding-bottom 16, gap 12; each row
// padding 16, gap 12, radius 8, shadow 0 0 10px -1.8px rgba(0,0,0,.15)).
//
// Icons are the exact Figma SVG paths. The chevron and the group icon came
// from Figma as <mask>-based SVGs; react-native-svg@15.3.0 doesn't render
// <mask>, so both are rebuilt as plain fills (same paths, same colors).
//
// Route names (AppNavigator.tsx / BottomTabNavigator.tsx):
//   Forums is a bottom tab inside 'MainApp'; EditProfile and Events are
//   top-level stack screens.

import React from 'react';
import {View, Text, StyleSheet, TouchableOpacity} from 'react-native';
import Svg, {Path} from 'react-native-svg';

interface Props {
  navigation?: any;
}

