// ─── Component ──────────────────────────────────────────────────────────────
const EmptyCoursesIOS = ({navigation}: Props) => {
  const rows = [
    {
      key: 'forums',
      Icon: ChatIcon,
      title: 'Join the discussions',
      description: 'Ask questions and share experience in the forums',
      onPress: () => navigation?.navigate?.('MainApp', {screen: 'Forums'}),
    },
    {
      key: 'industry',
      Icon: GroupIcon,
      title: 'Find your industry group',
      description: 'Connect with PMs in your sector',
      // Opens Forums on the "PM by Industry" tab with its industry filter
      // sheet already open. Needs the small openTab hook in ForumsScreen.tsx
      // (see CoursesScreen.ios-empty.patch.md, edit 4).
      onPress: () =>
        navigation?.navigate?.('MainApp', {
          screen: 'Forums',
          params: {openTab: 'industry'},
        }),
    },
    {
      key: 'profile',
      Icon: PersonIcon,
      title: 'Complete your profile',
      description: 'Add your projects and experience to turn your profile into a portfolio',
      onPress: () => navigation?.navigate?.('EditProfile'),
    },
    {
      key: 'events',
      Icon: CalendarIcon,
      title: 'Join upcoming events',
      description: 'Free IPM events and webinars for members',
      onPress: () => navigation?.navigate?.('Events'),
    },
  ];

  return (
    <View style={styles.container}>
      <View style={styles.headingBlock}>
        <Text style={styles.heading}>{"You don't have any courses yet"}</Text>
        <View style={styles.headingUnderline} />
        <Text style={styles.subtext}>{"Courses you're enrolled in will appear here."}</Text>
      </View>

      <View style={styles.sections}>
        {/* Not in the CSS notes but present in the Figma frame. */}
        <Text style={styles.sectionTitle}>{'Get started on IPM Hub'}</Text>

        {rows.map(({key, Icon, title, description, onPress}) => (
          <TouchableOpacity key={key} style={styles.row} onPress={onPress} activeOpacity={0.7}>
            <View style={styles.iconTile}>
              <Icon />
            </View>
            <View style={styles.rowText}>
              <Text style={styles.rowTitle}>{title}</Text>
              <Text style={styles.rowDescription}>{description}</Text>
            </View>
            <ChevronRight />
          </TouchableOpacity>
        ))}
      </View>
    </View>
  );
};

